WITH filtered AS (SELECT *, GREATEST(discount, amount) AS greatest_discount_amount FROM orders WHERE order_date >= DATE '2023-04-16' AND channel IS NOT NULL) SELECT *, NTILE(10) OVER w_part AS discount_bucket, CORR(amount, discount) OVER (PARTITION BY status) AS corr_amount_discount, DENSE_RANK() OVER (PARTITION BY status, store_id ORDER BY shipping_fee NULLS LAST) AS shipping_fee_dense_rank FROM filtered WINDOW w_part AS (PARTITION BY channel, status ORDER BY discount DESC, id);
